import React, { FC } from 'react';

interface FilterSelectorProps {
  title: string;
  options: string[];
  onFilterChange: (filterType: string, value: string | number) => void;
}

const FilterSelector: FC<FilterSelectorProps> = ({ title, options, onFilterChange }) => {
  return (
    <label>
      {title}:
      <select onChange={(e) => onFilterChange(title.toLowerCase(), e.target.value)}>
        <option value="">Select a {title.toLowerCase()}</option>
        {options.map((option: string) => (
          <option key={option} value={option}>
            {title === 'Price' ? `< ${option}` : option}
          </option>
        ))}
      </select>
    </label>
  );
};

export default FilterSelector;
